    if (selected === undefined) {
        return refuse(
            binding,
            policy,
            'undeclared-response',
            `${binding.tool} received an HTTP ${reply.status} representation its contract does not declare`,
        );
    }
    const structured: { [key: string]: unknown } = {
        ok: !isError,
        status: reply.status,
        mediaType: reply.mediaType,
    };
    let text: string;
